:root {
  --ink: #eaf7ff;
  --ink-dim: #8aa4b8;
  --ink-faint: #536b7d;
  --cyan: #74efff;
  --cyan-soft: #3ec7e0;
  --cyan-deep: #0b6e84;
  --amber: #ffc36b;
  --coral: #ff5f7d;
  --night: #03060d;
  --panel: rgba(5, 13, 24, 0.72);
  --line: rgba(140, 214, 235, 0.2);
  --line-strong: rgba(140, 214, 235, 0.42);
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
  --sans: "Helvetica Neue", "Segoe UI", system-ui, -apple-system, sans-serif;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
}

html {
  background: var(--night);
}

body {
  overflow: hidden;
  color: var(--ink);
  background: var(--night);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

button,
input {
  font: inherit;
}

button {
  color: inherit;
}

kbd {
  display: inline-block;
  min-width: 1.7em;
  padding: 0.08em 0.4em 0.12em;
  border: 1px solid rgba(178, 232, 247, 0.28);
  border-bottom-color: rgba(178, 232, 247, 0.12);
  border-radius: 4px;
  background: rgba(160, 224, 244, 0.08);
  color: #c8f4ff;
  font-family: var(--mono);
  font-size: 0.72em;
  line-height: 1.2;
  letter-spacing: 0.08em;
  text-align: center;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #03060d;
  isolation: isolate;
  user-select: none;
  -webkit-user-select: none;
}

#sky {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.app.is-playing #sky {
  cursor: none;
}

.lens-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 92% 82% at 50% 45%, transparent 38%, rgba(0, 3, 8, 0.28) 72%, rgba(0, 2, 6, 0.78) 100%),
    linear-gradient(180deg, rgba(0, 3, 8, 0.32), transparent 16%, transparent 72%, rgba(0, 2, 6, 0.45));
  z-index: 2;
}

.lens-scanlines {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0.35;
  background: repeating-linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.02) 0px,
    rgba(255, 255, 255, 0.02) 1px,
    transparent 1px,
    transparent 3px
  );
  mix-blend-mode: soft-light;
}

/* ---------------------------------------------------------------- HUD */

.hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 6;
  display: grid;
  grid-template-columns: 1fr minmax(240px, 380px) 1fr;
  align-items: start;
  gap: clamp(16px, 3vw, 56px);
  padding: max(20px, env(safe-area-inset-top)) clamp(18px, 3.2vw, 48px) 0;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-8px);
  transition: opacity 0.6s var(--ease), transform 0.6s var(--ease);
}

.is-playing .hud,
.is-paused .hud {
  opacity: 1;
  transform: none;
